CREATE TABLE catalog_places (id CHAR(36) PRIMARY KEY, public_id VARCHAR(160) NOT NULL UNIQUE, workspace_id CHAR(36) NOT NULL, payload JSON NOT NULL, state ENUM('draft','review','published') NOT NULL DEFAULT 'draft', revision INT UNSIGNED NOT NULL DEFAULT 1, approved_revision INT UNSIGNED, created_by CHAR(36) NOT NULL, approved_by CHAR(36), synthetic BOOLEAN NOT NULL DEFAULT FALSE, request_key CHAR(36) NOT NULL, request_hash CHAR(64) NOT NULL, name_key CHAR(64) NOT NULL, address_key CHAR(64), website_key CHAR(64), updated_at DATETIME(3) NOT NULL, UNIQUE(workspace_id,request_key), UNIQUE(workspace_id,name_key), UNIQUE(workspace_id,address_key), UNIQUE(workspace_id,website_key), FOREIGN KEY(workspace_id) REFERENCES workspaces(id), FOREIGN KEY(created_by) REFERENCES profiles(id), FOREIGN KEY(approved_by) REFERENCES profiles(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
